@Service
public class PaymentService {

    @CircuitBreaker(name = "paymentGateway", fallbackMethod = "fallbackPayment")
    public PaymentResponse processPayment(PaymentRequest request) {
        // Call to external payment gateway that might fail
        return restTemplate.postForObject("https://api.payment-gateway.com/charge", request, PaymentResponse.class);
    }

    public PaymentResponse fallbackPayment(PaymentRequest request, CallNotPermittedException ex) {
        // Fallback logic when circuit is OPEN
        return new PaymentResponse("FAILED", "Payment gateway unavailable. Please try again later.");
    }
}
